INSERT INTO `ec_products` VALUES (1,'Elegant Check Blazer',NULL,'A timeless essential with a clean silhouette, delivering everyday comfort with effortless style. Crafted from soft, breathable fabric with a relaxed yet structured fit.','<p>Designed for modern wardrobes, this piece combines simplicity, versatility, and premium comfort in one refined silhouette. Crafted from soft, breathable fabric, it features a relaxed yet structured fit that makes it perfect for layering or wearing on its own.</p>\n                                <p>The classic silhouette and subtle detailing create a polished look suitable for casual outings, work-from-anywhere days, or weekend downtime. Durable stitching and carefully finished seams ensure long-lasting wear, while the neutral tone allows easy pairing with denim, tailored trousers, or outerwear.</p>\n                                <p>Whether you\'re building a capsule wardrobe or looking for a dependable everyday staple, this piece is made to keep your style understated, confident, and effortlessly cool.</p>','published','[\"products\\/product-1.webp\",\"products\\/product-details-1.webp\",\"products\\/product-details-2.webp\",\"products\\/product-details-3.webp\",\"products\\/product-details-4.webp\",\"products\\/product-details-5.webp\",\"products\\/product-details-6.webp\"]',NULL,'OR-1-627-V0',0,45,0,1,'in_stock',1,NULL,1,0,3,9,3.00,0,142.5,NULL,NULL,NULL,19,17,9,381,NULL,'standard',2460,'2026-06-01 03:24:23','2026-06-01 03:24:24',0,'Botble\\ACL\\Models\\User',NULL,'physical',NULL,NULL,NULL,0,0,'auto_generate',0,0,0,NULL),(2,'Classic Oversized Brown Hoodie',NULL,'A timeless essential with a clean silhouette, delivering everyday comfort with effortless style. Crafted from soft, breathable fabric with a relaxed yet structured fit.','<p>Designed for modern wardrobes, this piece combines simplicity, versatility, and premium comfort in one refined silhouette. Crafted from soft, breathable fabric, it features a relaxed yet structured