INSERT INTO `pages` VALUES (1,'Homepage','[hero-banner style=\"1\" title=\"We Create Digital Experiences\" subtitle=\"B2B Marketing Agency\" description=\"We help brands grow through creative strategy, bold design, and digital innovation.\" background_image=\"pages/bg-img.webp\" image=\"pages/img-1.webp\" background_video=\"/themes/orisa/videos/video-1.mp4\" primary_action_label=\"Explore All Work\" primary_action_url=\"/portfolio\" primary_action_icon=\"ti ti-arrow-up-right\" secondary_action_label=\"How We Work\" secondary_action_url=\"/about-1\" secondary_action_icon=\"ti ti-phone\"][/hero-banner]\n[about-us-information style=\"1\" title=\"We shape animated stories that inspire and engage, uniting thoughtful design, fluid motion, and digital craftsmanship.\" subtitle=\"About Us\" description=\"We build &lt;b&gt;bold&lt;/b&gt;, resilient brands designed to leave a lasting mark on the world.\" primary_action_label=\"GET IN TOUCH\" primary_action_url=\"/contact-1\" avatars_quantity=\"5\" avatars_image_1=\"testimonials/avatar-1.webp\" avatars_image_2=\"testimonials/avatar-2.webp\" avatars_image_3=\"testimonials/avatar-3.webp\" avatars_image_4=\"testimonials/avatar-4.webp\" avatars_image_5=\"testimonials/avatar-5.webp\" experience_years=\"15\" quantity=\"2\" title_1=\"Creative Expertise\" description_1=\"With over a decade of design expertise, we create tailored solutions that engage audiences, build meaningful connections, and elevate brands with creativity and intent.\" image_1=\"pages/img-3.webp\" style_image_1=\"pages/img-3.webp\" title_2=\"Experience &amp; Innovation\" description_2=\"Backed by a decade of creative experience, we craft visual experiences that bring together strategy, design, and technology to grow brands, inspire audiences, and create meaningful impact.\" image_2=\"pages/img-4.webp\" style_image_2=\"pages/img-4.webp\"][/about-us-information]\n[partners style=\"1\" quantity=\"10\" name_1=\"Framer\" image_1=\"partners/1.webp\" url_1=\"https://googl