INSERT INTO `pages_translations` VALUES ('ar',1,'الصفحة الرئيسية',NULL,'[hero-banner style=\"1\" title=\"نحن نخلق تجارب رقمية\" subtitle=\"وكالة التسويق B2B\" description=\"نحن نساعد العلامات التجارية على النمو من خلال الإستراتيجية الإبداعية والتصميم الجريء والابتكار الرقمي.\" background_image=\"pages/bg-img.webp\" image=\"pages/img-1.webp\" background_video=\"/themes/orisa/videos/video-1.mp4\" primary_action_label=\"استكشاف كل العمل\" primary_action_url=\"/portfolio\" primary_action_icon=\"ti ti-arrow-up-right\" secondary_action_label=\"كيف نعمل\" secondary_action_url=\"/about-1\" secondary_action_icon=\"ti ti-phone\"][/hero-banner]\n[about-us-information style=\"1\" title=\"نقوم بتشكيل قصص الرسوم المتحركة التي تلهم وتتفاعل، وتوحد التصميم المدروس، والحركة السلسة، والحرفية الرقمية.\" subtitle=\"معلومات عنا\" description=\"نحن نبني <b>bold</b>، وهي علامات تجارية مرنة مصممة لترك بصمة دائمة في العالم.\" primary_action_label=\"تواصل معنا\" primary_action_url=\"/contact-1\" avatars_quantity=\"5\" avatars_image_1=\"testimonials/avatar-1.webp\" avatars_image_2=\"testimonials/avatar-2.webp\" avatars_image_3=\"testimonials/avatar-3.webp\" avatars_image_4=\"testimonials/avatar-4.webp\" avatars_image_5=\"testimonials/avatar-5.webp\" experience_years=\"15\" quantity=\"2\" title_1=\"الخبرة الإبداعية\" description_1=\"مع أكثر من عقد من الخبرة في التصميم، نقوم بإنشاء حلول مخصصة تجذب الجماهير، وتبني اتصالات هادفة، وترفع من مستوى العلامات التجارية بالإبداع والنية.\" image_1=\"pages/img-3.webp\" style_image_1=\"pages/img-3.webp\" title_2=\"الخبرة والابتكار\" description_2=\"مدعومين بعقد من الخبرة الإبداعية، نقوم بصياغة تجارب مرئية تجمع بين الإستراتيجية والتصميم والتكنولوجيا لتنمية العلامات التجارية وإلهام الجماهير وإحداث تأثير مفيد.\" image_2=\"pages/img-4.webp\" style_image_2=\"pages/img-4.webp\"][/about-us-information]\n[partners style=\"1\" quantity=\"10\" name_1=\"Framer\" image_1=\"partners/1.webp\" url_1=\"https://google.com\" open_in_new_tab_1=\"1\" name_2=\"Reddit\" image_2=\"partners/2.webp\" url_2=\"https://google.com\" open_in_new_tab_2=\"1\" name_3=\"Netflix\" image_3=\"partners/3.webp\" url_3=\"https://google.com\" open_in_new_tab_3=\"1\" name_4=\"Microsoft\" image_4=\"partners/4.webp\" url_4=\"https://google.com\" open_in_new_tab_4=\"1\" name_5=\"Discover\" image_5=\"partners/5.webp\" url_5=\"https://google.com\" open_in_new_tab_5=\"1\" name_6=\"Lemon Squeezy\" image_6=\"partners/6.webp\" url_6=\"https://google.com\" open_in_new_tab_6=\"1\" name_7=\"PayPal\" image_7=\"partners/7.webp\" url_7=\"https://google.com\" open_in_new_tab_7=\"1\" name_8=\"Mailchimp\" image_8=\"partners/8.webp\" url_8=\"https://google.com\" open_in_new_tab_8=\"1\" name_9=\"Shopify\" image_9=\"partners/4.webp\" url_9=\"https://google.com\" open_in_new_tab_9=\"1\" name_10=\"Slack\" image_10=\"partners/7.webp\" url_10=\"https://google.com\" open_in_new_tab_10=\"1\"][/partners]\n[services style=\"1\" subtitle=\"حلولنا\" description=\"منذ عام 2012\" service_ids=\"2,1,3,4\" experience_years=\"38\"][/services]\n[projects style=\"1\" title=\"عمل مختار نفتخر به\" subtitle=\"مَلَفّ\" description=\"مجموعة مختارة من المشاريع حيث تجتمع الإستراتيجية والإبداع والحرفية معًا لبناء تجارب علامة تجارية هادفة ودائمة.\" primary_action_label=\"عرض أحدث المشاريع\" primary_action_url=\"/portfolio\"][/projects]\n[testimonials style=\"1\" title=\"موثوق بها من قبل العملاء\" subtitle=\"تجارب العملاء الحقيقية التي تتحدث عن قوة عملنا.\" quantity=\"6\" name_1=\"لوكاس مورينو\" role_1=\"مدير المنتج\" company_1=\"برشلونة، اسبانيا\" quote_1=\"كان التعاون سلسًا من البداية إلى النهاية. أدت قرارات تجربة المستخدم الخاصة بهم إلى تحسين منتجنا بشكل كبير...\" rating_1=\"4\" avatar_1=\"general/testimonial-avatar-1.webp\" company_logo_1=\"general/testimonial-logo-architect.webp\" name_2=\"هانا لي\" role_2=\"المدير الإبداعي\" company_2=\"استوديو الحركية\" quote_2=\"مزيج نادر من الخبرة التقنية والرؤية الفنية. شعرت النتيجة النهائية بأنها متميزة وهادفة.\" rating_2=\"5\" avatar_2=\"general/testimonial-avatar-2.webp\" company_logo_2=\"general/testimonial-logo-cloudly.webp\" name_3=\"اميليا رايت\" role_3=\"رئيس التسويق\" company_3=\"لندن، المملكة المتحدة\" quote_3=\"لم يقدموا تصميمًا فحسب، بل قدموا تجربة كاملة للعلامة التجارية. استراتيجي ومبدع وموجه نحو التفاصيل بشكل لا يصدق.\" rating_3=\"5\" avatar_3=\"general/testimonial-avatar-3.webp\" company_logo_3=\"general/testimonial-logo-techlify.webp\" name_4=\"ديفيد تشين\" role_4=\"CTO\" company_4=\"حلول نوفاتيك\" quote_4=\"اهتمام متميز بالتفاصيل وفهم عميق لتجربة المستخدم. لقد حولوا منصتنا إلى ما هو أبعد من التوقعات.\" rating_4=\"5\" avatar_4=\"general/testimonial-avatar-1.webp\" company_logo_4=\"general/testimonial-logo-cloudly.webp\" name_5=\"صوفيا مارتينيز\" role_5=\"مدير العلامة التجارية\" company_5=\"وكالة لومينا\" quote_5=\"عمليتهم الإبداعية لا مثيل لها. لقد تجاوز كل تسليم توقعاتنا وكان له صدى لدى جمهورنا.\" rating_5=\"5\" avatar_5=\"general/testimonial-avatar-2.webp\" company_logo_5=\"general/testimonial-logo-architect.webp\" name_6=\"أوليفر جرانت\" role_6=\"مؤسس\" company_6=\"استوديو بيكسل كرافت\" quote_6=\"كان العمل مع هذا الفريق بمثابة وجود قسم تصميم داخلي. سريع وموثوق ومبدع إلى ما لا نهاية.\" rating_6=\"4\" avatar_6=\"general/testimonial-avatar-3.webp\" company_logo_6=\"general/testimonial-logo-techlify.webp\"][/testimonials]\n[about-us-information style=\"4\" subtitle=\"لماذا تختارنا؟\" title=\"تحقيق نتائج قابلة للقياس من خلال توازن قوي بين التميز في التصميم والأداء الوظيفي.\" description=\"Orisa&trade; goes beyond aesthetics&mdash;bringing clarity through motion, flexible structure, and practical tools that help you move faster without defining your identity.\" image_1=\"pages/img-15.webp\" style_image_1=\"pages/img-15.webp\" image_2=\"pages/img-16.webp\" style_image_2=\"pages/img-16.webp\" image_3=\"general/logo-white.png\" style_image_3=\"general/logo-white.png\" quantity=\"2\" title_1=\"1.8M\" description_1=\"نشط\nحالات حية\" content_1=\"نحن نقدم دائمًا للأشخاص حلاً كاملاً يركز على أي عمل تجاري\" title_2=\"16K\" description_2=\"موثوق به\nالشركاء\" content_2=\"لأنه في بعض الأحيان يكون التصميم الأفضل هو الذي لا يتعين عليك التفكير فيه.\"][/about-us-information]\n[site-statistics style=\"1\" quantity=\"5\" value_1=\"10\" suffix_1=\"K+\" label_1=\"سنوات من الممارسة الإبداعية\" value_2=\"50\" suffix_2=\"K+\" label_2=\"مشاريع وضعت بعناية\" value_3=\"16\" suffix_3=\"K+\" label_3=\"العلامات التجارية المتعاونة معها\" value_4=\"20\" suffix_4=\"M+\" label_4=\"إجمالي التمويل المدعوم\" value_5=\"98\" suffix_5=\"%\" label_5=\"معدل رضا العملاء\"][/site-statistics]\n[teams style=\"2\" subtitle=\"لماذا تختارنا؟\" title=\"تعرف على العقول التي تقف وراء Orisa Studio. اعتمد على المتخصصين ذوي الخبرة لدينا لإيجاد حلول مصممة خصيصًا لك.\" primary_action_label=\"انضم إلى فريقنا\" primary_action_url=\"/contact\" description=\"&lt;h3 class=\\\"h6 fw-600\\\"&gt;We are here&lt;/h3&gt;&lt;div class=\\\"d-flex flex-md-row flex-column gap-md-5 gap-4\\\"&gt;&lt;span class=\\\"fz-font-md neutral-500\\\"&gt;205 North Michigan Avenue, Suite 810&lt;br&gt;Chicago, 60601, USA&lt;br&gt;Phone: &lt;span class=\\\"neutral-900\\\"&gt;&lt;a href=\\\"tel:+1234567890\\\"&gt;+1234567890&lt;/a&gt;&lt;/span&gt;&lt;br&gt;Email: &lt;span class=\\\"neutral-900\\\"&gt;&lt;a href=\\\"mailto:hello@orisa.com\\\"&gt;hello@orisa.com&lt;/a&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=\\\"fz-font-md neutral-500 ps-md-5\\\"&gt;245 Fifth Avenue, Suite 1800&lt;br&gt;New York, NY 10016, USA&lt;br&gt;Phone: &lt;span class=\\\"neutral-900\\\"&gt;&lt;a href=\\\"tel:+2125557398\\\"&gt;+2125557398&lt;/a&gt;&lt;/span&gt;&lt;br&gt;Email: &lt;span class=\\\"neutral-900\\\"&gt;&lt;a href=\\\"mailto:sale@orisa.com\\\"&gt;sale@orisa.com&lt;/a&gt;&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;\" team_ids=\"1,2,3,4\"][/teams]\n[skills-carousel quantity=\"10\" name_1=\"web3\" name_2=\"B2B &amp; B2C\" name_3=\"منصات SaaS\" name_4=\"اتجاه الفن\" name_5=\"تطبيقات الويب والجوال\" name_6=\"تصميم الحركة\" name_7=\"UX/UI\" name_8=\"العلامة التجارية\" name_9=\"تصميم المفهوم\" name_10=\"العروض التقديمية\"][/skills-carousel]\n[faqs title=\"Answered questions. Everything you might want to know&mdash;up front.\" subtitle=\"FAQ\" image=\"pages/img-21.webp\" description=\"لا يوجد حتى الآن الحظ؟ يمكننا المساعدة!\" secondary_description=\"اسمحوا لنا أن نعرف كيف يمكننا المساعدة\" primary_action_label=\"مركز الدعم\" primary_action_url=\"/faqs\" category_ids=\"1,2,3\" limit=\"8\"][/faqs]\n[call-to-action style=\"1\" title=\"Let\'s Create &lt;br&gt; Meaning Together\" description=\"استوديو إبداعي يصوغ تجارب رقمية جريئة تركز على المستخدم. في أوريسا، نمزج بين الإستراتيجية والتصميم والابتكار لمساعدة العلامات التجارية على التميز والنمو.\" primary_action_label=\"احجز مكالمة الآن\" primary_action_url=\"/contact-1\" image=\"pages/img-22.webp\"][/call-to-action]\n[blog-posts subtitle=\"داخل الشركة\" title=\"أحدث المشاركات من مدونة <br> وصفحة معجبي الحدث\" description=\"رؤى واتجاهات وقصص من فريق Orisa.\" paginate=\"4\" action_label=\"جميع المقالات\" action_url=\"/blog\"][/blog-posts]'),('ar',2,'مَلَفّ',NULL,'[projects title=\"عملنا\" subtitle=\"مَلَفّ\" description=\"اكتشف المشاريع التي نفخر بها.\"][/projects]'),('ar',3,'الخدمات 1',NULL,'[about-us-information style=\"7\" title=\"Orisa Studio&lt;sup&gt;&reg;&lt;/sup&gt;\" email=\"hello@orisa.com\" phone=\"(212) 555-7398\" image=\"pages/img-153.webp\"][/about-us-information]\n[services style=\"1\" subtitle=\"حلولنا\" title=\"خدماتنا\" description=\"حلول إبداعية تتمحور حول أهداف علامتك التجارية واحتياجات الجمهور.\" service_ids=\"2,1,3,4\"][/services]\n[image-mosaic quantity=\"18\" column_speed_1=\"-0.1\" column_speed_2=\"0.8\" column_speed_3=\"-0.1\" image_1=\"pages/img-140.webp\" image_2=\"pages/img-142.webp\" image_3=\"pages/img-143.webp\" image_4=\"pages/img-141.webp\" image_5=\"pages/img-140.webp\" image_6=\"pages/img-139.webp\" image_7=\"pages/img-147.webp\" image_8=\"pages/img-144.webp\" image_9=\"pages/img-145.webp\" image_10=\"pages/img-146.webp\" image_11=\"pages/img-148.webp\" image_12=\"pages/img-149.webp\" image_13=\"pages/img-126.webp\" image_14=\"pages/img-146.webp\" image_15=\"pages/img-147.webp\" image_16=\"pages/img-5.webp\" image_17=\"pages/img-150.webp\" image_18=\"pages/img-151.webp\"][/image-mosaic]\n[pricing-plans style=\"3\" title=\"تم تصميم خطط التسعير الإستراتيجية لمواءمة الجهود الرقمية مع أهداف عملك\" subtitle=\"الأسعار والخطط\" description=\"اختر الخطة التي تناسب مشروعك وميزانيتك.\" quantity=\"3\" name_1=\"Starter\" description_1=\"A solid digital foundation focused on clarity, usability, and performance essentials.\" monthly_price_1=\"$1,200\" yearly_price_1=\"$12,000\" features_1=\"Digital strategy setup{{NEWLINE}}Digital audit &amp; Insights{{NEWLINE}}Positioning &amp; Messaging{{NEWLINE}}SEO &amp; Technical setup{{NEWLINE}}Analytics tracking\" button_label_1=\"Get Started\" button_url_1=\"/contact-1\" name_2=\"Growth\" description_2=\"A performance-driven plan to accelerate acquisition and conversion.\" monthly_price_2=\"$2,800\" yearly_price_2=\"$28,000\" features_2=\"Growth strategy{{NEWLINE}}Conversion optimization{{NEWLINE}}SEO &amp; Content performance{{NEWLINE}}Campaign setup &amp; Reporting{{NEWLINE}}Advance analytics tracking\" button_label_2=\"Choose Growth\" button_url_2=\"/contact-1\" is_featured_2=\"yes\" name_3=\"Scale\" description_3=\"A long-term digital partnership for sustainable growth at scale.\" monthly_price_3=\"$3,600\" yearly_price_3=\"$36,000\" features_3=\"Full strategy &amp; execution{{NEWLINE}}Dedicated success manager{{NEWLINE}}Advanced SEO &amp; content{{NEWLINE}}Multi-channel campaigns{{NEWLINE}}Custom reporting &amp; insights\" button_label_3=\"Scale Your Business\" button_url_3=\"/contact-1\"][/pricing-plans]\n[contact-form style=\"3\" subtitle=\"cONTACT US\" title=\"Get in touch\" description=\"Start the conversation by sharing your vision. &lt;br&gt;Our team will respond within 1&ndash;2 business days.\" address=\"205 North Michigan Avenue, Suite 810{{NEWLINE}}Chicago, 60601, USA\" phone=\"+1234567890\" email=\"hello@orisa.com\" address_2=\"245 Fifth Avenue, Suite 1800{{NEWLINE}}New York, NY 10016, USA\" phone_2=\"+2125557398\" email_2=\"sale@orisa.com\" display_fields=\"phone,email\" mandatory_fields=\"name,email,phone,content\" form_title=\"\"][/contact-form]'),('ar',4,'الخدمات 2',NULL,'[about-us-information style=\"8\" subtitle=\"إبداعي - مبتكر - رشيق\" title=\"خدماتنا\" description=\"نحول الأفكار إلى حلول رقمية عالية التأثير تجذب العملاء وتعزز التحويلات وتسرع النمو المستدام.\" image=\"pages/img-154.webp\"][/about-us-information]\n[keyword-ticker scroll_direction=\"left\" quantity=\"12\" name_1=\"Research &amp; Insights\" name_2=\"Purpose, Mission &amp; Vision\" name_3=\"Value Proposition\" name_4=\"Brand Positioning\" name_5=\"Brand Architecture\" name_6=\"Brand Personality Trait\" name_7=\"UX Research &amp; User Journeys\" name_8=\"Information Architecture\" name_9=\"Wireframing &amp; Prototyping\" name_10=\"Design Systems\" name_11=\"Digital Strategy\" name_12=\"Interface Design (UI)\"][/keyword-ticker]\n[services style=\"2\" subtitle=\"الأشياء التي نقدمها\" title=\"الخدمات الإبداعية\" service_ids=\"2,1,3,4\"][/services]\n[testimonials style=\"2\" subtitle=\"الشهادات\" title=\"استمع إلى عملائي السعداء\" testimonial_ids=\"1,2,3,4,5\"][/testimonials]\n[faqs style=\"4\" title=\"Frequently Asked Questions\" category_ids=\"1,2,3\" limit=\"8\"][/faqs]'),('ar',5,'الخدمات 3',NULL,'[about-us-information style=\"9\" subtitle=\"إبداعي - مبتكر - رشيق\" title=\"خدمات\" description=\"نحول الأفكار إلى حلول رقمية عالية التأثير تجذب العملاء وتعزز التحويلات وتسرع النمو المستدام.\" image=\"pages/img-155.webp\"][/about-us-information]\n[service-cards quantity=\"4\" title_1=\"Strategy &amp; Research\" description_1=\"Through research, analysis, and positioning, we build a clear foundation for meaningful digital growth.\" image_1=\"pages/img-76.webp\" url_1=\"#\" title_2=\"Design &amp; Experience\" description_2=\"Every interaction is crafted to balance beauty, usability, and brand personality.\" image_2=\"pages/img-77.webp\" url_2=\"#\" title_3=\"Network Integration\" description_3=\"From on-premise to cloud environments, we ensure seamless communication, scalability, and operational stability.\" image_3=\"pages/img-78.webp\" url_3=\"#\" title_4=\"Build &amp; Launch\" description_4=\"Bring ideas to life with clean, scalable, and performance-driven builds. From development to launch, we focus on reliability and long-term growth.\" image_4=\"pages/img-80.webp\" url_4=\"#\"][/service-cards]\n[content-block style=\"11\" subtitle=\"خطوة بخطوة\" title=\"عملي\" description=\"أقوم بدمج البحث المعماري العميق واستراتيجية البيانات الصارمة وهندسة الإنتاج لبناء أنظمة ذكاء اصطناعي مرنة.\" quantity=\"4\" title_1=\"تدقيق النظام واكتشافه\" description_1=\"2-3 Weeks|Mapping the infrastructure|تعمق في البنية التحتية الحالية وخطوط البيانات وأهداف العمل.\" image_1=\"pages/img-138.webp\" style_image_1=\"pages/img-138.webp\" title_2=\"الإستراتيجية المعمارية\" description_2=\"3-4 Weeks|Defining the AI logic|تصميم بنيات ML قابلة للتطوير تتماشى مع متطلبات الأداء والتكلفة.\" image_2=\"pages/img-139.webp\" style_image_2=\"pages/img-139.webp\" title_3=\"الهندسة والنشر\" description_3=\"8-12 Weeks|Building production-ready models|قم ببناء النماذج واختبارها ونشرها باستخدام خطوط أنابيب CI/CD ومراقبتها.\" image_3=\"pages/img-140.webp\" style_image_3=\"pages/img-140.webp\" title_4=\"MLOps والتطور\" description_4=\"Ongoing|Continuous optimization|المراقبة المستمرة للنموذج وإعادة التدريب وتحسين الإنتاج.\" image_4=\"pages/img-141.webp\" style_image_4=\"pages/img-141.webp\"][/content-block]\n[site-statistics style=\"2\" quantity=\"3\" title_1=\"الإيرادات مدفوعة من خلال استراتيجية <br> الرقمية\" data_1=\"28\" unit_1=\"M+\" title_2=\"العملاء المتوقعون المؤهلون الذين تم إنشاؤهم <br>\" data_2=\"64\" unit_2=\"K+\" title_3=\"العلامات التجارية تحجيم <br> مع Orisa\" data_3=\"190\" unit_3=\"+\"][/site-statistics]\n[image-gallery quantity=\"5\" image_1=\"pages/img-48.webp\" alt_1=\"